import streamlit as st
import pandas as pd
from frontend.api_client import api_client, APIError
from frontend.components.disclaimer import render_disclaimer_banner
from frontend.components.export import render_csv_download_button
from frontend.components.kpi_card import format_currency_inr

st.set_page_config(page_title="Anomaly Screening | MPLADS FundGuard", page_icon="🛡️", layout="wide")

st.title("🛡️ Multi-Dimensional Anomaly Screening")
render_disclaimer_banner()

st.markdown(
    """
    **Methodology Note:** Anomaly scores are generated by an **Isolation Forest ensemble (10 random seeds, max_samples=1024)**, 
    evaluating works against **stratified peer groups** (same work type and state, with fallback to national medians). 
    Top-ranked works predominantly exhibit unusually fragmented payment structures (high installment and vendor counts) 
    or extreme expenditures relative to peer medians. 
    **Scores are exploratory screening ranks for manual audit prioritization, not probabilities or proof of wrongdoing.**
    """
)

# Filter bar
st.markdown("### 1. Screening Search & Filters")
fcol1, fcol2, fcol3 = st.columns(3)
with fcol1:
    stage_choice = st.selectbox(
        "Lifecycle Cohort",
        options=["all", "Completed", "In-Progress"],
        format_func=lambda x: "All Scored Cohorts" if x == "all" else f"{x} Works Cohort"
    )
with fcol2:
    state_input = st.text_input("State Filter (Optional)", placeholder="e.g. Rajasthan, Uttar Pradesh, Tamil Nadu")
with fcol3:
    search_query = st.text_input("Keyword Search (Work ID, MP, Constituency, Work)", placeholder="e.g. WS/MP..., water, road")

scol1, scol2, scol3 = st.columns(3)
with scol1:
    min_score = st.slider("Minimum Anomaly Score", min_value=0.0, max_value=1.0, value=0.50, step=0.05)
with scol2:
    page_size = st.selectbox("Page Size", options=[25, 50, 100], index=1)
with scol3:
    page_num = st.number_input("Page Number", min_value=1, value=1, step=1)

stage_param = None if stage_choice == "all" else stage_choice
state_param = state_input.strip() if state_input else None
search_param = search_query.strip() if search_query else None

try:
    anomalies, pagination = api_client.get_anomalies(
        stage=stage_param,
        state=state_param,
        min_score=float(min_score),
        search=search_param,
        sort_by="anomaly_score",
        sort_order="desc",
        page=int(page_num),
        page_size=int(page_size)
    )
    total_records = pagination.get("total_records", 0)
    total_pages = pagination.get("total_pages", 0)

    st.write(f"Screening results: **{len(anomalies)}** works displayed of **{total_records:,}** matching criteria (Page {page_num} of {max(1, total_pages)}):")

    if anomalies:
        table_df = pd.DataFrame(anomalies)

        display_df = pd.DataFrame({
            "Work ID": table_df["work_id"],
            "Stage": table_df["stage"],
            "Rank": table_df["rank_in_stage"],
            "Anomaly Score": table_df["anomaly_score"].apply(lambda s: f"{s:.4f}"),
            "Key Contributing Factors": table_df["top_anomalous_factors"],
            "State": table_df["state"],
            "Constituency": table_df["constituency"],
            "MP Name": table_df["mp_name"],
            "Work Type": table_df["work"],
            "Sanctioned (₹)": table_df["sanction_amount"].apply(lambda x: f"₹{x:,.0f}" if pd.notna(x) else "—"),
            "Settled Exp (₹)": table_df["total_exp_settled"].apply(lambda x: f"₹{x:,.0f}" if pd.notna(x) else "—"),
            "Peer Tier": table_df["peer_tier"].fillna("—")
        })

        st.dataframe(display_df, use_container_width=True)

        render_csv_download_button(
            df=display_df,
            filename=f"anomaly_screening_{stage_choice}_page{page_num}.csv",
            button_label="📥 Export Screened Works to Sanitized CSV"
        )

        st.markdown("---")
        st.subheader("2. Detailed Work Record Inspection")
        st.caption("Inspect full multi-dimensional breakdown, peer comparisons, and ledger timeline for any specific project.")

        # Let user select from the current table or type custom Work ID
        work_options = list(table_df["work_id"])
        selected_work = st.selectbox("Select a Work ID to Inspect in Detail", options=work_options)

        if selected_work:
            try:
                detail = api_client.get_anomaly_detail(work_id=selected_work)
                
                st.markdown(f"#### 🔍 Detailed Dossier: `{detail.get('work_id')}`")
                st.info(f"**Work Description:** {detail.get('work_description') or detail.get('work')}")

                # Metric row 1: Financial & Score
                mcol1, mcol2, mcol3, mcol4 = st.columns(4)
                mcol1.metric("Anomaly Score", f"{detail.get('anomaly_score', 0):.4f}")
                mcol2.metric("Rank in Stage", f"#{detail.get('rank_in_stage', 0):,}")
                mcol3.metric("Sanctioned Amount", format_currency_inr(detail.get("sanction_amount")))
                mcol4.metric("Settled Expenditure", format_currency_inr(detail.get("total_exp_settled")))

                # Metric row 2: Fragmentation & Peer comparison
                pcol1, pcol2, pcol3, pcol4 = st.columns(4)
                pcol1.metric("Payment Installments", detail.get("installments_count", 0))
                pcol2.metric("Unique Vendors", detail.get("vendors_count", 0))
                pcol3.metric("Primary Vendor", detail.get("primary_vendor", "Unknown"))
                pcol4.metric("Peer Group Median", format_currency_inr(detail.get("peer_median_settled")))

                # Detailed breakdown tabs
                t_factors, t_timeline, t_flags = st.tabs(["🏷️ Extreme Factors & Peer Comparison", "⏱️ Timeline & Duration", "🚩 Ledger Rule Flags"])

                with t_factors:
                    st.markdown("**Top Anomalous Drivers:**")
                    st.warning(detail.get("top_anomalous_factors") or "None identified")
                    st.markdown(f"- **Peer Benchmark Tier:** `{detail.get('peer_tier', 'Tier 1')}`")
                    st.markdown(f"- **Log Relative Cost Difference vs Peer Median:** `{detail.get('paid_vs_peer_log', 0):.3f}`")
                    st.markdown(f"- **Utilization Ratio:** `{detail.get('utilization_ratio', 0) * 100:.1f}%`")
                    st.markdown(f"- **Cost Variance (Settled - Sanctioned):** `{format_currency_inr(detail.get('cost_variance', 0))}`")

                with t_timeline:
                    dcol1, dcol2, dcol3 = st.columns(3)
                    dcol1.markdown(f"**Recommended Date:** `{detail.get('recommended_date') or '—'}`")
                    dcol1.markdown(f"**Sanction Date:** `{detail.get('sanction_date') or '—'}`")
                    dcol1.markdown(f"**Completion Date:** `{detail.get('completion_date') or '—'}`")

                    dcol2.markdown(f"**Sanction Approval Lag:** `{detail.get('sanction_approval_days') or 0:.0f} days`")
                    dcol2.markdown(f"**Execution Duration:** `{detail.get('execution_duration_days') or 0:.0f} days`")
                    dcol2.markdown(f"**First Payment Lag:** `{detail.get('first_payment_lag_days') or 0:.0f} days`")

                    dcol3.markdown(f"**Settled Disbursements:** `{detail.get('settled_count', 0)}`")
                    dcol3.markdown(f"**Pending Disbursements:** `{detail.get('in_progress_count', 0)}`")

                with t_flags:
                    flags = detail.get("rule_flags", {})
                    active_flags = {k: v for k, v in flags.items() if v == 1}
                    if active_flags:
                        st.warning(f"Active Rule Flags Triggered: {list(active_flags.keys())}")
                    else:
                        st.success("No deterministic ledger rule flags triggered for this work.")
                    
                    st.caption(f"**Methodology Note:** {detail.get('methodology_note')}")

            except Exception as e:
                st.error(f"Error fetching detail for {selected_work}: {e}")

    else:
        st.info("No works found matching the selected filters.")

except Exception as e:
    st.error(f"Error executing anomaly screening query: {e}")
